import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

// 1. Immutable Money Value Object
public final class Money {
    private final double amount;
    private final String currency;

    public Money(double amount, String currency) {
        if (amount < 0) throw new IllegalArgumentException("Amount cannot be negative.");
        this.amount = amount;
        this.currency = (currency != null) ? currency.toUpperCase() : "USD";
    }

    public Money add(Money other) {
        if (other == null || !this.currency.equals(other.currency)) {
            throw new IllegalArgumentException("Currency mismatch or null Money object.");
        }
        return new Money(this.amount + other.amount, this.currency);
    }

    public double getAmount() { return amount; }
    public String getCurrency() { return currency; }

    @Override
    public String toString() {
        return String.format("$%.2f %s", amount, currency);
    }
}

// 2. Immutable OrderItem
final class OrderItem {
    private final String sku;
    private final String name;
    private final int quantity;
    private final Money unitPrice;

    public OrderItem(String sku, String name, int quantity, Money unitPrice) {
        if (quantity <= 0) throw new IllegalArgumentException("Quantity must be positive.");
        this.sku = sku;
        this.name = name;
        this.quantity = quantity;
        this.unitPrice = unitPrice;
    }

    public Money getSubtotal() {
        return new Money(quantity * unitPrice.getAmount(), unitPrice.getCurrency());
    }

    public String getSku() { return sku; }
    public String getName() { return name; }
    public int getQuantity() { return quantity; }
    public Money getUnitPrice() { return unitPrice; }
}

// 3. Immutable Order with Defensive Copying
final class Order {
    private final String orderId;
    private final String customerId;
    private final List<OrderItem> items;
    private final long timestamp;

    public Order(String orderId, String customerId, List<OrderItem> items) {
        if (items == null || items.isEmpty()) throw new IllegalArgumentException("Order items required.");
        this.orderId = orderId;
        this.customerId = customerId;
        this.timestamp = System.currentTimeMillis();

        // DEFENSIVE COPY: Copy all items into a new list, then wrap in unmodifiableList
        List<OrderItem> defensiveCopy = new ArrayList<>();
        for (OrderItem item : items) {
            defensiveCopy.add(item); // OrderItem is already immutable
        }
        this.items = Collections.unmodifiableList(defensiveCopy);
    }

    public Money computeTotal() {
        Money total = new Money(0.0, "USD");
        for (OrderItem item : items) {
            total = total.add(item.getSubtotal());
        }
        return total;
    }

    public List<OrderItem> getItems() {
        return items; // Already wrapped in unmodifiableList
    }

    public String getOrderId() { return orderId; }
    public String getCustomerId() { return customerId; }
    public long getTimestamp() { return timestamp; }
}

